def check_sum_to_zero(elements):
    """
    Check if any two distinct elements sum to zero.
    Returns a tuple (bool, pair) where pair is the two elements if found.
    """
    # Use a set for O(1) lookups
    seen = set()

    for elem in elements:
        target = -elem
        if target in seen:
            return True, (target, elem)
        seen.add(elem)

    return False, None

