def int_to_roman(n: int) -> str:
    if not 0 <= n <= 3999:
        raise ValueError("Number out of range (0–3999)")
    thousands = ["", "m", "mm", "mmm"]
    hundreds  = ["", "c", "cc", "ccc", "cd", "d", "dc", "dcc", "dccc", "cm"]
    tens      = ["", "x", "xx", "xxx", "xl", "l", "lx", "lxx", "lxxx", "xc"]
    ones      = ["", "i", "ii", "iii", "iv", "v", "vi", "vii", "viii", "ix"]
    return (
        thousands[n // 1000] +
        hundreds[(n // 100) % 10] +
        tens[(n // 10) % 10] +
        ones[n % 10]
    )

