def split_and_filter(s: str, n: int) -> list[str]:
    """
    Splits a string `s` into words and returns a list of words that contain
    exactly `n` consonants. It ignores vowels and empty strings during the count.
    """
    vowels = set("aeiouAEIOU")

    def count_consonants(word: str) -> int:
        return sum(1 for char in word if char.isalpha() and char not in vowels)

    return [
        word
        for word in s.split()
        if word and count_consonants(word) == n
    ]
